/*
 * DataCore 设计令牌（Phase 0 草案）
 * 第一层 · 全局色阶：blue / gray 两组 0–1000（只在本文件出现）
 * 第二层 · 语义别名：--primary / --foreground / --border …（组件只能用这一层）
 * 值用 HSL 三元组，便于 Tailwind 透明度修饰。
 */
:root {
  /* —— 全局：DataCore Blue（保持现有蓝色系，H≈221，600 级与主站 #2563EB 一致） —— */
  --blue-50: 214 100% 97%;  --blue-100: 214 95% 93%;  --blue-200: 213 97% 87%;
  --blue-300: 212 96% 78%;  --blue-400: 213 94% 68%;  --blue-500: 217 91% 60%;
  --blue-600: 221 83% 53%;  --blue-700: 224 76% 48%;  --blue-800: 226 71% 40%;
  --blue-900: 224 64% 33%;
  /* —— 全局：中性灰（比 slate 降低饱和，避免整屏“发蓝发雾”） —— */
  --gray-0: 0 0% 100%;     --gray-25: 220 20% 98.5%; --gray-50: 220 16% 96.5%;
  --gray-100: 220 14% 94%; --gray-200: 220 13% 90%;  --gray-300: 218 11% 82%;
  --gray-400: 218 9% 64%;  --gray-500: 220 8% 46%;   --gray-600: 220 9% 36%;
  --gray-700: 220 12% 26%; --gray-800: 222 16% 16%;  --gray-900: 224 20% 10%;
  --gray-950: 225 24% 6%;

  /* —— 语义 · 浅色 —— */
  --canvas: var(--gray-25);          /* 页面底 */
  --background: var(--gray-0);       /* 卡片/面板 */
  --foreground: var(--gray-900);
  --card: var(--gray-0);  --card-foreground: var(--gray-900);
  --popover: var(--gray-0); --popover-foreground: var(--gray-900);
  --primary: var(--blue-600); --primary-hover: var(--blue-700);
  --primary-foreground: 0 0% 100%; --primary-soft: var(--blue-50);
  --secondary: var(--gray-50); --secondary-foreground: var(--gray-800);
  --muted: var(--gray-50); --muted-foreground: var(--gray-500);
  --subtle: var(--gray-400);
  --accent: var(--gray-100); --accent-foreground: var(--gray-900);
  --border: var(--gray-200); --input: var(--gray-300); --ring: var(--blue-500);
  --success: 158 84% 30%; --success-soft: 152 60% 95%;
  --warning: 32 95% 40%;  --warning-soft: 43 100% 95%;
  --danger: 0 72% 48%;    --danger-soft: 0 86% 97%;
  --agent: 256 56% 52%;   --agent-soft: 256 80% 97%;
  --shadow: 222 30% 12%;
  /* 数据可视化：首色 = 品牌蓝，其余避开语义色（红/绿只表示好坏，不作分组色） */
  --chart-1: 221 83% 53%; --chart-2: 188 78% 38%; --chart-3: 33 92% 50%;
  --chart-4: 268 55% 56%; --chart-5: 340 65% 52%; --chart-6: 220 9% 46%;
  color-scheme: light;
}

[data-theme="dark"] {
  --canvas: var(--gray-950);
  --background: 224 20% 9%;
  --foreground: 220 14% 94%;
  --card: 224 20% 9%;  --card-foreground: 220 14% 94%;
  --popover: 222 18% 12%; --popover-foreground: 220 14% 94%;
  --primary: 217 91% 62%; --primary-hover: 213 94% 70%;
  --primary-foreground: 224 30% 8%; --primary-soft: 222 50% 18%;
  --secondary: 222 16% 15%; --secondary-foreground: 220 14% 90%;
  --muted: 222 16% 14%; --muted-foreground: 218 10% 62%;
  --subtle: 218 9% 46%;
  --accent: 222 16% 17%; --accent-foreground: 220 14% 94%;
  --border: 222 14% 20%; --input: 222 12% 26%; --ring: 217 91% 62%;
  --success: 156 55% 52%; --success-soft: 160 40% 14%;
  --warning: 38 92% 60%;  --warning-soft: 36 50% 15%;
  --danger: 0 84% 68%;    --danger-soft: 0 45% 16%;
  --agent: 256 75% 74%;   --agent-soft: 256 35% 18%;
  --shadow: 0 0% 0%;
  --chart-1: 217 91% 64%; --chart-2: 186 70% 50%; --chart-3: 36 92% 60%;
  --chart-4: 266 70% 72%; --chart-5: 340 75% 66%; --chart-6: 218 10% 62%;
  color-scheme: dark;
}

/**
 * DataCore Tailwind preset（Phase 0 草案）。
 * 语义令牌全部来自 CSS 变量（src/tokens.css），浅/深两套；组件只用语义名，不用原色。
 */
import animate from "tailwindcss-animate";

const v = (name) => `hsl(var(--${name}) / <alpha-value>)`;

export default {
  darkMode: ["class", '[data-theme="dark"]'],
  content: ["./index.html", "./src/**/*.{ts,tsx}"],
  theme: {
    extend: {
      fontFamily: {
        sans: ["Inter", '"PingFang SC"', '"Noto Sans SC"', '"Microsoft YaHei"', "system-ui", "sans-serif"],
        mono: ['"JetBrains Mono"', '"SF Mono"', "Menlo", "monospace"],
      },
      fontSize: {
        // 产品界面基准 14px；说明文字 12px；标题按 1.25 级差
        xs: ["12px", "18px"], sm: ["13px", "20px"], base: ["14px", "22px"], md: ["16px", "24px"],
        lg: ["18px", "26px"], xl: ["20px", "28px"], "2xl": ["24px", "32px"], "3xl": ["30px", "38px"],
      },
      colors: {
        border: v("border"), input: v("input"), ring: v("ring"),
        background: v("background"), foreground: v("foreground"),
        canvas: v("canvas"),
        primary: { DEFAULT: v("primary"), foreground: v("primary-foreground"), soft: v("primary-soft"), hover: v("primary-hover") },
        secondary: { DEFAULT: v("secondary"), foreground: v("secondary-foreground") },
        muted: { DEFAULT: v("muted"), foreground: v("muted-foreground") },
        subtle: v("subtle"),
        accent: { DEFAULT: v("accent"), foreground: v("accent-foreground") },
        popover: { DEFAULT: v("popover"), foreground: v("popover-foreground") },
        card: { DEFAULT: v("card"), foreground: v("card-foreground") },
        success: { DEFAULT: v("success"), soft: v("success-soft") },
        warning: { DEFAULT: v("warning"), soft: v("warning-soft") },
        danger: { DEFAULT: v("danger"), soft: v("danger-soft"), foreground: v("primary-foreground") },
        // shadcn 组件使用 destructive，与 danger 同义
        destructive: { DEFAULT: v("danger"), foreground: v("primary-foreground") },
        agent: { DEFAULT: v("agent"), soft: v("agent-soft") },
        chart: { 1: v("chart-1"), 2: v("chart-2"), 3: v("chart-3"), 4: v("chart-4"), 5: v("chart-5"), 6: v("chart-6") },
      },
      borderRadius: { sm: "4px", DEFAULT: "6px", md: "6px", lg: "8px", xl: "12px" },
      boxShadow: {
        xs: "0 1px 2px hsl(var(--shadow) / 0.06)",
        sm: "0 1px 2px hsl(var(--shadow) / 0.06), 0 1px 3px hsl(var(--shadow) / 0.08)",
        md: "0 4px 12px hsl(var(--shadow) / 0.10)",
        lg: "0 12px 32px hsl(var(--shadow) / 0.14)",
      },
      transitionTimingFunction: { standard: "cubic-bezier(0.2, 0, 0, 1)" },
      transitionDuration: { fast: "120ms", base: "180ms" },
    },
  },
  plugins: [animate],
};
